char* sanitize_input(char* input) {
    // Simple sanitization: remove any non-alphanumeric characters
    static char sanitized[BUFFER_SIZE];
    int j = 0;
    for (int i = 0; input[i] != '\0' && j < BUFFER_SIZE - 1; i++) {
        if (isalnum(input[i])) {
            sanitized[j++] = input[i];
        }
    }
    sanitized[j] = '\0';
    return sanitized;
}

